import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { pathToFileURL } from 'node:url';
const { PilotBroker, literalSearchAdapter, PILOT_MANIFEST, applyTaskMutation, evaluateCandidate, proveSandboxDenials, verifyPilotRuntime, OllamaModelDriver, EVALUATOR_NODE_SHA256 } = await import(pathToFileURL(path.join(process.env.REPO, 'scripts/competitive-coding-pilot.ts')).href);
const root = fs.realpathSync(process.env.OWNED);
const privateRoot = path.join(root, 'private-evaluator');
const reference = path.join(root, 'reference-control');
const control = path.join(root, 'broker-control');
const participant = path.join(root, 'model-participant');
const output = path.join(root, 'evidence.json');
const digest = value => createHash('sha256').update(value).digest('hex');
const task = PILOT_MANIFEST.tasks[0];
const runtime = { path: path.join(root, 'runtime-node'), expectedVersion: 'v24.16.0', expectedSha256: EVALUATOR_NODE_SHA256 };
const evaluation = { privateRoot, runtime };
const record = { schemaVersion: 1, date: '2026-10-06', developmentOnly: true, modelDrivenSuccess: false, sourceScope: 'one already-exposed Axios helper, not a full repository', taskId: task.id, prompt: task.prompt, modelAttemptBudget: { attempts: 1, condition: 'literal-unindexed', maxChatRequests: 4, maxGeneratedTokens: 2048, maxWallMs: 120000, requestTimeoutMs: 60000, maxBrokerToolCalls: 12, modelSettings: PILOT_MANIFEST.model }, stages: [], brokerControl: [], network: [] };
const checkpoint = () => fs.writeFileSync(output, JSON.stringify(record, null, 2) + '\n');
const stage = async (name, run) => {
  const started = Date.now();
  try { const result = await run(); record.stages.push({ name, result, durationMs: Date.now() - started }); checkpoint(); return result; }
  catch (error) { record.stages.push({ name, error: { name: error.name, message: error.message, ...(error.result ? { result: error.result } : {}) }, durationMs: Date.now() - started }); checkpoint(); throw error; }
};
try {
  if (process.argv[2] !== '--model') {
    fs.mkdirSync(privateRoot, { mode: 0o700 });
    fs.copyFileSync(process.env.RUNTIME_SOURCE, runtime.path, fs.constants.COPYFILE_EXCL);
    fs.chmodSync(runtime.path, 0o500);
    const clean = fs.readFileSync(process.env.SOURCE_FILE, 'utf8');
    record.source = { sha256: digest(clean), content: clean };
    for (const workspace of [reference, control, participant]) {
      const file = path.join(workspace, task.mutation.file);
      fs.mkdirSync(path.dirname(file), { recursive: true });
      fs.writeFileSync(file, clean);
      if (workspace !== reference) applyTaskMutation(workspace, task);
    }
    record.runtime = await stage('pinned-runtime-and-model-verification', () => verifyPilotRuntime(runtime));
    await stage('real-sandbox-denials', () => proveSandboxDenials(control, evaluation));
    const original = await stage('reference-in-private-independent-evaluator', () => evaluateCandidate(reference, task, evaluation));
    const initial = await stage('initial-mutant-in-private-independent-evaluator', () => evaluateCandidate(control, task, evaluation));
    if (!original.passed || original.exitCode !== 0 || initial.passed || initial.exitCode !== 0 || initial.error) throw new Error('behavioral reference/mutant preflight failed');
    const broker = new PilotBroker(control, literalSearchAdapter);
    record.brokerControlAllowedFiles = broker.allowedFiles;
    for (const call of [
      { name: 'list', arguments: {} },
      { name: 'search', arguments: { query: 'isAbsoluteURL', limit: 5 } },
      { name: 'read', arguments: { path: task.mutation.file } },
      { name: 'read', arguments: { path: '../reference-control/' + task.mutation.file } },
      { name: 'replace_unique', arguments: { path: task.mutation.file, oldText: task.mutation.newText, newText: task.mutation.oldText } },
    ]) record.brokerControl.push({ call, result: await broker.execute(call) });
    record.controlPatch = { before: fs.readFileSync(path.join(participant, task.mutation.file), 'utf8'), after: fs.readFileSync(path.join(control, task.mutation.file), 'utf8'), toolCalls: broker.callCount, label: 'deterministic infrastructure control, not model-driven repair' };
    const repaired = await stage('broker-patch-in-private-independent-evaluator', () => evaluateCandidate(control, task, evaluation));
    if (!repaired.passed) throw new Error('real broker infrastructure control failed');
    record.infrastructureMechanicsProved = true;
    checkpoint();
  } else {
    const prior = JSON.parse(fs.readFileSync(output, 'utf8'));
    Object.assign(record, prior);
    if (!record.infrastructureMechanicsProved) throw new Error('model execution requires successful mechanics preflight');
    const broker = new PilotBroker(participant, literalSearchAdapter);
    record.modelAllowedFiles = broker.allowedFiles;
    record.modelInitial = fs.readFileSync(path.join(participant, task.mutation.file), 'utf8');
    let chatRequests = 0;
    const actualFetch = async (url, init) => {
      if (url.endsWith('/api/chat') && ++chatRequests > record.modelAttemptBudget.maxChatRequests) throw new Error('predeclared feasibility chat-request cap exhausted');
      const entry = { url, method: init.method, ...(init.body ? { body: JSON.parse(init.body) } : {}), startedAt: new Date().toISOString() };
      record.network.push(entry);
      checkpoint();
      try {
        const response = await fetch(url, init);
        entry.status = response.status;
        entry.response = await response.clone().text();
        entry.finishedAt = new Date().toISOString();
        checkpoint();
        return response;
      } catch (error) { entry.error = { name: error.name, message: error.message }; entry.finishedAt = new Date().toISOString(); checkpoint(); throw error; }
    };
    const started = Date.now();
    try {
      record.model = await new OllamaModelDriver(actualFetch).run({ prompt: task.prompt, broker, deadlineMs: started + record.modelAttemptBudget.maxWallMs, maxGeneratedTokens: record.modelAttemptBudget.maxGeneratedTokens, requestTimeoutMs: record.modelAttemptBudget.requestTimeoutMs });
    } catch (error) {
      record.modelError = { name: error.name, message: error.message, transcript: error.transcript, promptTokens: error.promptTokens, generatedTokens: error.generatedTokens };
    }
    record.modelDurationMs = Date.now() - started;
    record.modelToolCalls = broker.callCount;
    record.modelChatRequestsSent = record.network.filter(entry => entry.url.endsWith('/api/chat')).length;
    record.modelFinal = fs.readFileSync(path.join(participant, task.mutation.file), 'utf8');
    record.modelPatchValidity = { valid: record.modelInitial !== record.modelFinal && fs.readdirSync(path.join(participant, 'lib/helpers')).join() === 'isAbsoluteURL.js', expectedFile: task.mutation.file, changed: record.modelInitial !== record.modelFinal };
    record.modelEvaluator = await stage('model-candidate-in-private-independent-evaluator', () => evaluateCandidate(participant, task, evaluation));
    record.modelDrivenSuccess = !record.modelError && record.modelEvaluator.passed && record.modelPatchValidity.valid;
    checkpoint();
  }
  console.log(JSON.stringify({ output, stages: record.stages, infrastructureMechanicsProved: record.infrastructureMechanicsProved, modelDrivenSuccess: record.modelDrivenSuccess, modelDurationMs: record.modelDurationMs, modelToolCalls: record.modelToolCalls, modelChatRequestsSent: record.modelChatRequestsSent, modelError: record.modelError?.message, modelEvaluator: record.modelEvaluator }));
} catch (error) { record.fatal = { name: error.name, message: error.message }; checkpoint(); console.error(error.stack); process.exitCode = 1; }

